<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { Icon } from "@iconify/vue";
import { API_BASE, authToken } from "../api";

// Management records are server-validated tagged JSON objects; forms use field definitions below.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;
type Field = { key: string; label: string; type?: "password" | "number" | "check" | "select" | "list" | "textarea" | "json"; options?: string[]; collection?: string; hint?: string; required?: boolean };
type Section = { id: string; name: string; icon: string; description: string; fields?: Field[] };

const sections: Section[] = [
  { id:"principals", name:"内部身份", icon:"lucide:users", description:"为人员和 Agent 建立稳定的 DeeBee 身份。默认没有资源权限；不会改变原本地管理员登录。", fields:[
    {key:"name",label:"显示名称",required:true},{key:"kind",label:"身份类型",type:"select",options:["human","service"]},
    {key:"username",label:"本地用户名",hint:"仅人员身份可选；留空表示仅通过外部身份或 API-Key 使用。"},
    {key:"password",label:"本地密码",type:"password",hint:"设置或重置至少 12 位；编辑时留空表示不修改。"},{key:"enabled",label:"启用内部身份",type:"check"}]},
  { id:"identity-sources", name:"身份源", icon:"lucide:shield-check", description:"API-Key 可本地签发或由可信服务验证；OIDC 接收面向 DeeBee 的 Access Token，不接受 ID Token 调 API。", fields:[
    {key:"name",label:"身份源名称",required:true},{key:"type",label:"身份源类型",type:"select",options:["api_key","oidc"]},
    {key:"validation_mode",label:"验证方式",type:"select",options:["managed","external_http","jwt","introspection"]},
    {key:"issuer",label:"OIDC Issuer",hint:"精确匹配，不带发现文档路径。"},{key:"audiences",label:"允许的 Audience",type:"list",hint:"逗号分隔；必须为 DeeBee 签发。"},
    {key:"allowed_algorithms",label:"允许的签名算法",type:"list",hint:"RS256 或 ES256，逗号分隔。"},
    {key:"field_mapping",label:"外部验证字段映射（JSON）",type:"json",hint:"可选，例如 {\"subject\":\"user.id\"}。"},
    {key:"verify_endpoint",label:"外部 API-Key 验证地址"},{key:"introspection_endpoint",label:"Token Introspection 地址"},
    {key:"service_client_id",label:"验证服务 Client ID"},{key:"service_secret",label:"验证服务凭据",type:"password"},
    {key:"required_scopes",label:"必需 Scopes",type:"list"},{key:"allowed_client_ids",label:"允许的客户端 ID",type:"list"},
    {key:"trusted_origins",label:"额外可信服务 Origin",type:"list",hint:"仅填经批准的 HTTPS Origin；不要添加不相关域名。"},
    {key:"browser_login",label:"启用 OIDC 浏览器登录",type:"check"},{key:"client_id",label:"浏览器登录 Client ID"},{key:"client_secret",label:"浏览器登录 Client Secret",type:"password"},
    {key:"enabled",label:"启用身份源",type:"check"}]},
  { id:"identity-bindings", name:"身份映射", icon:"lucide:link", description:"可信来源 + 稳定 Subject → DeeBee 内部身份。不能按昵称或邮箱自动合并。", fields:[
    {key:"source_id",label:"可信身份源",type:"select",collection:"identity-sources",required:true},
    {key:"subject",label:"外部 Subject",required:true,hint:"OIDC 的 sub，或外部 API-Key 验证服务返回的 subject。"},
    {key:"principal_id",label:"DeeBee 内部身份",type:"select",collection:"principals",required:true},{key:"enabled",label:"启用身份映射",type:"check"}]},
  { id:"resources", name:"机器与数据库", icon:"lucide:server", description:"新增服务只开放 SSH、MySQL、PostgreSQL。原工作台连接不自动对外公开，已有 RDP 不受影响。", fields:[
    {key:"name",label:"资源名称",required:true},{key:"type",label:"资源类型",type:"select",options:["ssh","mysql","postgresql"]},
    {key:"host",label:"主机地址",required:true},{key:"port",label:"端口",type:"number",required:true},
    {key:"database",label:"数据库名称",hint:"MySQL/PostgreSQL 必填，一个资源限定一个业务数据库。"},
    {key:"schemas",label:"PostgreSQL Schema",type:"list"},{key:"host_key",label:"SSH 主机 SHA256 指纹",hint:"从可信渠道核验，必须在用户认证前验证。"},
    {key:"host_key_algorithm",label:"SSH 主机密钥算法",type:"select",options:["ssh-ed25519","ecdsa-sha2-nistp256","rsa-sha2-512","rsa-sha2-256"]},
    {key:"tls",label:"验证数据库 TLS",type:"check"},{key:"ca_file",label:"服务器上的 CA 文件路径"},
    {key:"timeout_seconds",label:"执行超时上限（秒）",type:"number"},{key:"max_rows",label:"返回行数上限",type:"number"},
    {key:"enabled",label:"启用资源",type:"check"}]},
  { id:"accounts", name:"目标账号", icon:"lucide:key-round", description:"凭据只在受信任后端使用。先保存禁用账号 → 测试 → 核验实际权限 → 启用。连接成功不代表权限安全。", fields:[
    {key:"resource_id",label:"所属资源",type:"select",collection:"resources",required:true},{key:"name",label:"账号别名",required:true},
    {key:"username",label:"目标用户名",required:true},{key:"tier",label:"账号级别",type:"select",options:["normal","privileged"]},
    {key:"auth_method",label:"目标认证方式",type:"select",options:["password","private_key"]},{key:"password",label:"目标账号密码",type:"password"},
    {key:"private_key",label:"SSH 私钥",type:"textarea",hint:"只用于 SSH 私钥认证；保存后不回显。"},{key:"passphrase",label:"私钥口令",type:"password"},
    {key:"permission_confirmed",label:"已核验目标账号的真实权限",type:"check"},{key:"permission_note",label:"权限核验说明",type:"textarea",hint:"普通数据库账号必须真正只读；SSH 普通账号仍可修改它有权修改的文件。"},
    {key:"enabled",label:"启用账号（需先测试）",type:"check"}]},
  { id:"access-grants", name:"资源与特权授权", icon:"lucide:badge-check", description:"按“内部身份 × 资源”授权。勾选特权意味着持续授权，无逐次审批；不授予 DeeBee 管理员权限。", fields:[
    {key:"principal_id",label:"内部身份",type:"select",collection:"principals",required:true},{key:"resource_id",label:"目标资源",type:"select",collection:"resources",required:true},
    {key:"normal_account_id",label:"普通账号",type:"select",collection:"accounts",required:true},{key:"privileged_account_id",label:"特权账号（可选）",type:"select",collection:"accounts"},
    {key:"allow_privileged",label:"允许使用特权账号",type:"check",hint:"仅在调用显式请求 privileged 且凭据具备 privilege:use 时使用。"},
    {key:"actions",label:"允许动作 Scopes",type:"list"},{key:"limits",label:"执行限制（JSON）",type:"json"},
    {key:"expires_at",label:"授权到期 Unix 秒（可选）",type:"number"},{key:"enabled",label:"启用资源授权",type:"check"}]},
  { id:"api-keys", name:"API-Key", icon:"lucide:fingerprint", description:"为内部身份签发本地 Key，或在“身份源”接入外部 Key。新 Key 原文仅显示一次；权限只能缩小，不能扩大已有资源授权。", fields:[
    {key:"name",label:"Key 名称",required:true},{key:"principal_id",label:"内部身份",type:"select",collection:"principals",required:true},
    {key:"source_id",label:"本地 Key 身份源",type:"select",collection:"identity-sources",required:true},{key:"expires_in_days",label:"有效天数",type:"number"},
    {key:"scopes",label:"Scopes",type:"list",hint:"resources:read, ssh:exec, db:query；写入另需 db:write，特权另需 privilege:use。"},
    {key:"resource_ids",label:"资源 ID 上限（可选）",type:"list",hint:"留空仍受内部身份的显式资源授权约束。"}]},
  { id:"preview", name:"授权预览", icon:"lucide:scan-eye", description:"查看内部身份的资源与账号投射，检查 API-Key/Token 的能力上限是否进一步收紧权限。"},
  { id:"executions", name:"执行记录", icon:"lucide:activity", description:"执行实际使用的账号、状态与结果。unknown 需要核实远端状态，不应自动重放修改。"},
  { id:"audit-events", name:"审计日志", icon:"lucide:scroll-text", description:"按真实登录身份归档 MCP、授权用户、管理端和原工作台操作；请求与响应脱敏后各保留最多 1 KiB。"},
  { id:"integration", name:"Agent 接入", icon:"lucide:plug", description:"外部 Agent 通过 MCP 或 REST 接入，无需安装 SenseMate 或依赖 AgentMesh。"},
];
const location = window.location;
const isUser = ref(location.hash === "#access-user");
const loggedIn = ref(false); const busy = ref(false); const message = ref(""); const error = ref("");
const loginName = ref("admin"); const loginPassword = ref(""); const current = ref("principals");
const records = ref<Record<string, Row[]>>({}); const form = ref<Row | null>(null); const editing = ref<Row | null>(null);
const report = ref<Row | null>(null); const reportType = ref(""); const reportTitle = ref(""); const newKey = ref(""); const sourceCredential = ref(""); const testingSource = ref<Row | null>(null);
const csrf = ref(""); const me = ref<Row>({}); const status = ref<Row>({}); const loginSources = ref<Row[]>([]);
const previewPrincipal = ref(""); const previewScopes = ref("resources:read, ssh:exec, db:query");
const userResources = ref<Row[]>([]); const selectedResource = ref(""); const mode = ref("normal"); const operation = ref("db.query"); const command = ref("SELECT 1"); const userExecution = ref<Row | null>(null);
const configText = ref(""); const importPreview = ref<Row | null>(null);
const userSchema = ref<Row | null>(null);
const legacyItems = ref<Row[] | null>(null);
const auditActor = ref(""); const auditOperation = ref(""); const auditSurface = ref("");
async function previewLegacy(){await act(async()=>{legacyItems.value=(await request('/admin/v1/legacy-connections/preview')).items;});}
async function importLegacy(item:Row){await act(async()=>{reportType.value="generic";reportTitle.value="连接导入结果";report.value=await request('/admin/v1/legacy-connections/import','POST',{profile_id:item.id,fingerprint:item.fingerprint});await load();message.value='已建立禁用引用，原连接未改动。请核验传输安全和账号权限后再发布。';});}
watch([selectedResource,mode],()=>{userSchema.value=null;userExecution.value=null;operation.value=activeResource.value?.type==='ssh'?'ssh.exec':'db.query';});
const section = computed(()=>sections.find(s=>s.id===current.value)!);
const rows = computed(()=>records.value[current.value] || []);
const activeResource = computed(()=>userResources.value.find(r=>r.id===selectedResource.value));
const visibleFields = computed(()=>(section.value.fields||[]).filter(field=>{
  const f=form.value;if(!f)return true;
  if(current.value==="principals"&&f.kind==="service")return !["username","password"].includes(field.key);
  if(current.value==="identity-sources"){
    const always=["name","type","validation_mode","enabled"];
    if(always.includes(field.key))return true;
    if(f.validation_mode==="managed")return false;
    if(f.type==="api_key")return ["audiences","verify_endpoint","service_secret","required_scopes","allowed_client_ids","trusted_origins","field_mapping"].includes(field.key);
    if(["verify_endpoint","field_mapping"].includes(field.key))return false;
    if(["introspection_endpoint","service_client_id","service_secret"].includes(field.key))return f.validation_mode==="introspection";
    if(["client_id","client_secret"].includes(field.key))return f.browser_login;
  }
  if(current.value==="resources"){
    if(f.type==="ssh")return !["database","schemas","tls","ca_file","max_rows"].includes(field.key);
    if(["host_key","host_key_algorithm"].includes(field.key))return false;
    if(field.key==="schemas")return f.type==="postgresql";
  }
  if(current.value==="accounts"){
    if(["private_key","passphrase"].includes(field.key))return f.auth_method==="private_key";
    if(field.key==="password")return f.auth_method==="password";
  }
  return true;
}));
function fieldOptions(field:Field){if(field.key==="validation_mode")return form.value?.type==="oidc"?["jwt","introspection"]:["managed","external_http"];return field.options;}
watch(()=>form.value?.type,(value,previous)=>{if(!form.value||!previous||value===previous)return;if(current.value==="identity-sources")form.value.validation_mode=value==="oidc"?"jwt":"managed";if(current.value==="resources")form.value.port=value==="ssh"?22:value==="mysql"?3306:5432;});

async function request(path: string, method="GET", body?: unknown, admin=true): Promise<Row> {
  const headers: Record<string,string> = {};
  if(admin && authToken()) headers.Authorization=`Bearer ${authToken()}`;
  if(body!==undefined) headers["Content-Type"]="application/json";
  if(!admin && csrf.value) headers["X-CSRF-Token"]=csrf.value;
  const response=await fetch(`${API_BASE}${path}`,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:"same-origin"});
  const data=await response.json().catch(()=>({}));
  if(!response.ok) throw new Error(data.error?.message || (Array.isArray(data.detail)?data.detail.map((d:Row)=>d.msg).join("；"):data.detail) || `请求失败 ${response.status}`);
  return data;
}
async function act(action: ()=>Promise<void>) { busy.value=true; error.value=""; message.value=""; try{await action();}catch(e){error.value=e instanceof Error?e.message:"操作失败";}finally{busy.value=false;} }
async function load() {
  if(isUser.value){ const result=await request("/v1/me","GET",undefined,false); me.value=result;csrf.value=result.csrf || "";userResources.value=(await request("/v1/resources","GET",undefined,false)).resources;loggedIn.value=true;return; }
  status.value=await request("/admin/v1/status");
  for(const s of sections.filter(s=>s.fields)) records.value[s.id]=(await request(`/admin/v1/${s.id}`)).items;
  loggedIn.value=true;
  await refresh();
}
async function login(){await act(async()=>{if(isUser.value){const result=await request("/v1/local/login","POST",{username:loginName.value,password:loginPassword.value},false);csrf.value=result.csrf;}else{const result=await request("/auth/login","POST",{username:loginName.value,password:loginPassword.value},false);sessionStorage.setItem("deebee_token",result.token);}loginPassword.value="";await load();});}
async function refresh(){
  if(current.value==="audit-events"){
    const query=new URLSearchParams();if(auditActor.value)query.set("actor",auditActor.value);if(auditOperation.value)query.set("operation",auditOperation.value);if(auditSurface.value)query.set("surface",auditSurface.value);
    records.value[current.value]=(await request(`/admin/v1/audit-events?${query}`)).items;
  }else if(current.value==="executions")records.value[current.value]=(await request("/admin/v1/executions")).items;
  else if(section.value.fields)records.value[current.value]=(await request(`/admin/v1/${current.value}`)).items;
}
async function select(id:string){current.value=id;form.value=null;report.value=null;newKey.value="";await act(refresh);}
function options(field:Field):Row[]{let items=records.value[field.collection || ""] || [];if(field.key==="source_id"&&current.value==="api-keys")items=items.filter(i=>i.validation_mode==="managed"&&i.enabled);if(field.key.endsWith("account_id"))items=items.filter(i=>i.resource_id===form.value?.resource_id&&i.tier===(field.key==="normal_account_id"?"normal":"privileged"));return items;}
function start(item?:Row){
  editing.value=item||null;error.value="";report.value=null;newKey.value="";
  const defaults:Record<string,Row>={principals:{kind:"human",enabled:true},"identity-sources":{type:"api_key",validation_mode:"managed",enabled:false},"identity-bindings":{enabled:true},resources:{type:"ssh",port:22,schemas:["public"],tls:true,enabled:false,timeout_seconds:60,max_rows:1000},accounts:{tier:"normal",auth_method:"password",enabled:false,permission_confirmed:false},"access-grants":{enabled:true,allow_privileged:false,actions:["resources:read","ssh:exec","db:query","db:write","privilege:use"],limits:{timeout_seconds:60,max_rows:1000,max_output_bytes:1048576}},"api-keys":{source_id:"local_keys",expires_in_days:90,scopes:["resources:read","ssh:exec","db:query"]}};
  form.value={...defaults[current.value]};
  for(const f of section.value.fields||[]){let v=item?.[f.key]??form.value[f.key]??(f.key==="allowed_algorithms"?["RS256"]:f.key==="host_key_algorithm"?"ssh-ed25519":f.type==="check"?false:"");if(f.type==="password"||f.key==="private_key")v="";if(f.type==="list")v=Array.isArray(v)?v.join(", "):v;if(f.type==="json")v=JSON.stringify(v||{},null,2);form.value[f.key]=v;}
}
async function save(){await act(async()=>{if(!form.value)return;const body:Row={};for(const f of section.value.fields||[]){const value=form.value[f.key];body[f.key]=f.type==="json"?JSON.parse(String(value)||"{}"):f.type==="list"?String(value).split(",").map(v=>v.trim()).filter(Boolean):f.type==="number"?(value===""?null:Number(value)):value;}
  if(current.value==="principals"&&body.kind==="service"){body.username="";body.password="";}
  if(current.value==="api-keys"){const result=await request("/admin/v1/api-keys","POST",body);newKey.value=result.key;}
  else{if(editing.value)body.expected_version=editing.value.version;await request(`/admin/v1/${current.value}${editing.value?`/${editing.value.id}`:""}`,editing.value?"PATCH":"POST",body);}
  form.value=null;await load();message.value="已保存。授权变化会立即拒绝后续不再获准的操作。";
});}
async function toggle(item:Row){await act(async()=>{if(current.value==="api-keys"){await request(`/admin/v1/api-keys/${item.id}/revoke`,"POST");}else{await request(`/admin/v1/${current.value}/${item.id}`,"PATCH",{expected_version:item.version,enabled:!item.enabled});}await load();message.value=item.enabled?"已停用/撤销":"已启用";});}
async function testAccount(item:Row){await act(async()=>{const result=await request(`/admin/v1/accounts/${item.id}/test`,"POST");reportType.value="generic";reportTitle.value="账号测试结果";report.value=result.test_result;await load();message.value=result.test_result.connected?"连接测试完成，请核验权限后再启用账号。":"测试未通过，请检查配置。";});}
async function testSource(){await act(async()=>{if(!testingSource.value)return;reportType.value="generic";reportTitle.value="身份源测试结果";report.value=await request(`/admin/v1/identity-sources/${testingSource.value.id}/test`,"POST",{credential:sourceCredential.value});sourceCredential.value="";testingSource.value=null;});}
async function preview(){await act(async()=>{reportType.value="generic";reportTitle.value="授权预览";report.value=await request("/admin/v1/access-preview","POST",{principal_id:previewPrincipal.value,scopes:previewScopes.value.split(",").map(s=>s.trim()).filter(Boolean)});});}
async function inspectExecution(item:Row){await act(async()=>{reportType.value="execution";reportTitle.value=`执行详情 · ${item.execution_id||item.id}`;report.value=await request(`/admin/v1/executions/${item.id}`);});}
async function inspectAudit(item:Row){await act(async()=>{reportType.value="audit";reportTitle.value=`审计详情 · #${item.id}`;report.value=await request(`/admin/v1/audit-events/${item.id}`);});}
async function cancelAdmin(item:Row){await act(async()=>{reportType.value="execution";reportTitle.value=`执行取消结果 · ${item.execution_id||item.id}`;report.value=await request(`/admin/v1/executions/${item.id}/cancel`,"POST");await refresh();});}
async function exportConfig(){await act(async()=>{configText.value=JSON.stringify(await request("/admin/v1/access-config/export"),null,2);message.value="配置已导出到下方，不含密码、私钥或 Key。";});}
async function checkImport(){await act(async()=>{importPreview.value=await request("/admin/v1/access-config/import-preview","POST",JSON.parse(configText.value));});}
async function applyImport(){await act(async()=>{await request("/admin/v1/access-config/import","POST",JSON.parse(configText.value));importPreview.value=null;await load();message.value="配置已更新";});}
function chooseResource(){mode.value="normal";operation.value=activeResource.value?.type==="ssh"?"ssh.exec":"db.query";command.value=activeResource.value?.type==="ssh"?"id":"SELECT 1";userExecution.value=null;}
async function executeUser(){await act(async()=>{const path=operation.value==="ssh.exec"?"/v1/ssh/executions":operation.value==="db.execute"?"/v1/db/executions":"/v1/db/queries";const body:Row={resource_id:selectedResource.value,mode:mode.value,idempotency_key:crypto.randomUUID()};body[operation.value==="ssh.exec"?"command":"sql"]=command.value;userExecution.value=await request(path,"POST",body,false);});}
async function pollUser(cursor:unknown=""){await act(async()=>{if(userExecution.value)userExecution.value=await request(`/v1/executions/${userExecution.value.execution_id}${typeof cursor==='string'&&cursor?'?cursor='+encodeURIComponent(cursor):''}`,"GET",undefined,false);});}
async function loadSchema(cursor=""){await act(async()=>{userSchema.value=await request(`/v1/resources/${selectedResource.value}/schema?mode=${mode.value}&cursor=${encodeURIComponent(cursor)}`,"GET",undefined,false);});}
async function cancelUser(){await act(async()=>{if(userExecution.value)userExecution.value=await request(`/v1/executions/${userExecution.value.execution_id}/cancel`,"POST",{},false);});}
async function logout(){await act(async()=>{if(isUser.value)await request("/v1/logout","POST",{},false);else sessionStorage.removeItem("deebee_token");loggedIn.value=false;newKey.value="";});}
function label(collection:string,id:string){const row=records.value[collection]?.find(r=>r.id===id);return row?.name||row?.username||id;}
function summary(item:Row){if(current.value==="identity-bindings")return `${label("identity-sources",item.source_id)} / ${item.subject} → ${label("principals",item.principal_id)}`;if(current.value==="access-grants")return `${label("principals",item.principal_id)} → ${label("resources",item.resource_id)} · 特权${item.allow_privileged?"允许":"关闭"}`;if(current.value==="accounts")return `${item.username} · ${item.tier} · ${label("resources",item.resource_id)}`;if(current.value==="resources")return `${item.type} · ${item.host}:${item.port}${item.database?` / ${item.database}`:""}`;if(current.value==="identity-sources")return `${item.type} / ${item.validation_mode}`;if(current.value==="executions")return `${item.tool} · ${item.mode} · ${item.username}`;if(current.value==="audit-events")return `${item.actor_name||item.actor}（${item.actor_kind||"未知身份"}） · ${item.auth_method||"无认证"} · ${item.surface||"历史记录"}`;return item.kind||item.subject||item.principal_id||"";}
function formatTime(value:number){return value?new Date(value*1000).toLocaleString():"—";}
onMounted(async()=>{loginSources.value=(await request("/access/login-options","GET",undefined,false).catch(()=>({sources:[]}))).sources;if(!isUser.value&&!authToken())return;await act(load);});
</script>

<template>
  <div class="access-workspace">
    <header class="access-header"><a href="#" class="access-brand" @click.prevent="location.href=location.pathname"><span>D</span> DeeBee</a><strong>{{ isUser?"我的授权资源":"身份与访问" }}</strong><span class="access-subtitle">SSH · MySQL · PostgreSQL</span><a :href="isUser?'#access':'#access-user'" @click.prevent="location.href=location.pathname+(isUser?'#access':'#access-user'); location.reload()">{{ isUser?"管理入口":"映射用户入口" }}</a><a href="./">返回原工作台</a><button v-if="loggedIn" @click="logout">退出</button></header>
    <div v-if="error" role="alert" class="access-alert error">{{ error }}</div><div v-if="message" role="status" class="access-alert">{{ message }}</div>
    <main v-if="!loggedIn" class="access-login"><Icon icon="lucide:shield-check" width="34" /><h1>{{ isUser?"登录授权资源":"本地管理员登录" }}</h1><p>{{ isUser?"本地映射用户或已配置的企业身份源。":"使用原工作台的本地管理员账号，不改变现有登录。" }}</p><form @submit.prevent="login"><label>用户名<input v-model="loginName" autocomplete="username" required></label><label>密码<input v-model="loginPassword" type="password" autocomplete="current-password" required></label><button class="primary" :disabled="busy">{{ busy?"正在验证…":"登录" }}</button></form><a v-for="source in isUser?loginSources:[]" :key="source.id" :href="`${API_BASE}/auth/oidc/${source.id}/start`">使用 {{ source.name }} 登录</a></main>
    <div v-else-if="!isUser" class="access-layout">
      <nav aria-label="身份与访问导航"><button v-for="s in sections" :key="s.id" :class="{selected:current===s.id}" @click="select(s.id)"><Icon :icon="s.icon" width="18" />{{ s.name }}</button><p>独立管理入口<br>原工作台界面不变</p></nav>
      <main class="access-main">
        <div class="access-heading"><div><h1>{{ section.name }}</h1><p>{{ section.description }}</p></div><button v-if="section.fields&&!form" class="primary" @click="start()">{{ current==='api-keys'?'签发 Key':'新增' }}</button><button :disabled="busy" @click="act(refresh)">刷新</button></div>
        <section v-if="current==='audit-events'" class="access-filters"><label>用户 / 身份<input v-model="auditActor" placeholder="姓名或内部身份 ID"></label><label>操作<input v-model="auditOperation" placeholder="如 mcp.tool.ssh.exec"></label><label>入口<select v-model="auditSurface"><option value="">全部入口</option><option value="mcp">MCP</option><option value="access_ui">授权用户前端</option><option value="admin">管理端</option><option value="workbench">原工作台</option><option value="execution_worker">执行器</option><option value="control_plane">配置变更事件</option><option value="legacy_audit">旧版历史记录</option></select></label><button :disabled="busy" @click="act(refresh)">查询</button></section>
        <section v-if="newKey" class="access-secret" role="status"><h2>API-Key 仅显示一次</h2><p>离开此页后无法取回原文。不要写入聊天、日志或源码。</p><input aria-label="新 API-Key" :value="newKey" readonly @focus="($event.target as HTMLInputElement).select()"><button @click="newKey=''">已安全保存，隐藏原文</button></section>
        <form v-if="form" class="access-form" @submit.prevent="save"><h2>{{ editing?'编辑':'新增' }}{{ section.name }}</h2><div class="access-fields"><label v-for="field in visibleFields" :key="field.key" :class="{'check-field':field.type==='check','wide-field':(field.type==='textarea'||field.type==='json')}"><template v-if="field.type==='check'"><input v-model="form[field.key]" type="checkbox">{{ field.label }}</template><template v-else><span>{{ field.label }}</span><select v-if="field.type==='select'" v-model="form[field.key]" :required="field.required"><option value="">请选择</option><option v-for="value in fieldOptions(field)" :key="value" :value="value">{{ value }}</option><option v-for="item in options(field)" :key="item.id" :value="item.id">{{ item.name||item.subject||item.id }}{{ item.username?` · ${item.username}`:'' }}</option></select><textarea v-else-if="(field.type==='textarea'||field.type==='json')" v-model="form[field.key]" rows="3" :autocomplete="field.key==='private_key'?'off':undefined" /><input v-else v-model="form[field.key]" :type="field.type==='password'?'password':field.type==='number'?'number':'text'" :required="field.required" :autocomplete="field.type==='password'?'new-password':'off'"></template><small v-if="field.hint">{{ field.hint }}</small></label></div><div class="access-actions"><button class="primary" :disabled="busy">{{ busy?'保存中…':'保存' }}</button><button type="button" @click="form=null">取消</button></div></form>
        <section v-if="current==='preview'" class="access-panel"><label>内部身份<select v-model="previewPrincipal"><option value="">选择内部身份</option><option v-for="p in records.principals" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label>凭据 Scopes 上限<input v-model="previewScopes"></label><button class="primary" :disabled="busy||!previewPrincipal" @click="preview">预览有效资源与账号</button></section>
        <section v-if="current==='integration'" class="access-panel"><h2>外部 Agent 接入地址</h2><label>MCP URL<input :value="status.mcp_url" readonly></label><label>REST API<input :value="status.api_url" readonly></label><p>API-Key：<code>X-DeeBee-API-Key</code>；外部 Key 另传 <code>X-DeeBee-Identity-Source</code>。</p><p>OIDC：<code>Authorization: Bearer &lt;Access Token&gt;</code>。Opaque Token 需要身份源选择器。不能同时提交 Key 和 Token。</p><p>调用顺序：identity.me → resources.list → ssh.exec / db.query / db.execute → executions.get。</p><p>默认普通模式；特权必须显式传 <code>mode: privileged</code>。RDP 不在对外工具范围。</p><hr><h2>原连接安全接入</h2><p>只引用 SSH/MySQL/PostgreSQL，旧连接及凭据仍是权威来源，不复制秘密。刷新会禁用已建立的引用，要求重新核验；不会自动增加任何授权。</p><button :disabled="busy" @click="previewLegacy">预览原连接（只读）</button><div v-for="item in legacyItems" :key="item.id" class="access-panel"><strong>{{ item.name }} · {{ item.type }}</strong><p>{{ item.host }}:{{ item.port }} · {{ item.database }} · {{ item.username }}</p><p v-if="item.reason">{{ item.reason }}</p><button :disabled="busy||!item.supported" @click="importLegacy(item)">建立/刷新禁用引用</button></div><hr><h2>配置备份与导入</h2><p>导出不含秘密；导入前验证全部引用和版本，失败会整体回滚。新增账号先禁用导入，再单独录入凭据、核验。</p><button @click="exportConfig">导出无秘密配置</button><textarea v-model="configText" aria-label="配置 JSON" rows="10" placeholder="导出的配置或待校验的 JSON" /><div class="access-actions"><button :disabled="busy||!configText" @click="checkImport">校验导入差异</button><button v-if="importPreview" :disabled="busy" @click="applyImport">确认原子导入</button></div><pre v-if="importPreview">{{ JSON.stringify(importPreview,null,2) }}</pre></section>
        <div v-if="!form&&current!=='preview'&&current!=='integration'" class="access-table-wrap"><table class="access-table"><thead><tr><th>名称 / 标识</th><th>身份与范围</th><th>状态 / 时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><strong>{{ current==='audit-events'?(item.operation||item.action):(item.name||item.action||item.execution_id||item.subject||label('principals',item.principal_id)) }}</strong><small>{{ current==='audit-events'?item.request_id:item.id }}</small></td><td>{{ summary(item) }}<small v-if="current==='audit-events'">{{ item.method }} {{ item.path }}<template v-if="item.resource_id"> · 资源 {{ item.resource_id }}</template><template v-if="item.account_username"> · 账号 {{ item.account_username }} / {{ item.mode }}</template></small></td><td><span :class="['access-badge',item.enabled||item.status==='succeeded'||(current==='audit-events'&&item.status_code>=200&&item.status_code<400)?'good':'muted']">{{ current==='audit-events'?`${item.status_code||'—'} · ${item.duration_ms||0} ms`:(item.status||(item.enabled===undefined?'已记录':item.enabled?'已启用':'已停用')) }}</span><small v-if="current==='audit-events'">{{ formatTime(item.at) }}</small></td><td><div class="access-row-actions"><button v-if="section.fields&&current!=='api-keys'" @click="start(item)">编辑</button><button v-if="section.fields&&(current!=='api-keys'||item.enabled)" :disabled="busy" @click="toggle(item)">{{ current==='api-keys'?'撤销':item.enabled?'停用':'启用' }}</button><button v-if="current==='accounts'" :disabled="busy" @click="testAccount(item)">测试与核验</button><button v-if="current==='identity-sources'" @click="testingSource=item;sourceCredential=''">测试身份源</button><button v-if="current==='executions'" @click="inspectExecution(item)">查看结果</button><button v-if="current==='executions'&&!['succeeded','failed','cancelled','unknown'].includes(item.status)" @click="cancelAdmin(item)">请求取消</button><button v-if="current==='audit-events'" @click="inspectAudit(item)">打开详情</button></div></td></tr><tr v-if="!rows.length"><td colspan="4" class="access-empty">暂无记录。{{ section.fields?'点击“新增”开始配置。':'完成一次操作后可在这里查看。' }}</td></tr></tbody></table></div>
        <section v-if="testingSource" class="access-panel"><h2>测试 {{ testingSource.name }}</h2><label>测试凭据（可选，不保存）<input v-model="sourceCredential" type="password" autocomplete="off"></label><p>OIDC 留空可验证发现文档和签名公钥；完整身份映射需提供 Access Token。</p><button :disabled="busy" @click="testSource">执行验证</button><button @click="testingSource=null;sourceCredential=''">取消</button></section>
      </main>
    </div>
    <main v-else class="access-user-main"><h1>{{ me.principal?.name }} 的可用资源</h1><p>来源：{{ me.source_id }} · 仅显示当前身份和凭据获准的资源，目标秘密不会提供给调用者。</p><div class="access-resource-cards"><button v-for="r in userResources" :key="r.id" :class="{selected:selectedResource===r.id}" @click="selectedResource=r.id;chooseResource()"><Icon :icon="r.type==='ssh'?'lucide:terminal':'lucide:database'" width="24" /><strong>{{ r.name }}</strong><span>{{ r.type }} {{ r.database }}</span><small v-for="m in r.access_modes" :key="m.mode">{{ m.mode }} · {{ m.username }}</small></button></div><p v-if="!userResources.length" class="access-empty">当前身份没有可用资源，请联系本地管理员配置映射和授权。</p><section v-if="activeResource" class="access-panel"><h2>{{ activeResource.name }}</h2><label>账号模式<select v-model="mode"><option v-for="m in activeResource.access_modes" :key="m.mode" :value="m.mode">{{ m.mode }} · {{ m.username }}</option></select></label><button v-if="activeResource.type!=='ssh'" :disabled="busy" @click="loadSchema()">查看数据库结构</button><pre v-if="userSchema">{{ JSON.stringify(userSchema,null,2) }}</pre><button v-if="userSchema?.next_cursor" :disabled="busy" @click="loadSchema(userSchema.next_cursor)">下一页结构</button><label>操作<select v-model="operation"><option v-for="action in activeResource.access_modes.find((m:Row)=>m.mode===mode)?.actions.filter((a:string)=>a!=='db.schema')" :key="action" :value="action">{{ action }}</option></select></label><label>{{ activeResource.type==='ssh'?'SSH 命令':'SQL' }}<textarea v-model="command" rows="6" /></label><p v-if="mode==='privileged'" class="access-warning">正在使用已获持续授权的特权账号，操作可能修改目标系统；没有逐次人工审批。</p><button class="primary" :disabled="busy" @click="executeUser">提交执行</button><div v-if="userExecution" class="access-panel"><button :disabled="busy" @click="pollUser">刷新执行结果</button><button v-if="userExecution.result?.next_cursor" :disabled="busy" @click="pollUser(userExecution.result.next_cursor)">下一页结果</button><button :disabled="busy" @click="cancelUser">请求取消</button><pre>{{ JSON.stringify(userExecution,null,2) }}</pre></div></section></main>
    <div v-if="report" class="access-modal-backdrop" @click.self="report=null"><section class="access-modal" role="dialog" aria-modal="true" :aria-label="reportTitle"><div class="access-modal-header"><div><h2>{{ reportTitle||'详情' }}</h2><p v-if="reportType==='audit'">请求 ID：{{ report.request_id||'历史记录无请求 ID' }} · {{ formatTime(report.at) }}</p></div><button @click="report=null">关闭</button></div><template v-if="reportType==='audit'"><dl class="access-audit-grid"><div><dt>登录用户</dt><dd>{{ report.actor_name||report.actor }}</dd></div><div><dt>身份</dt><dd>{{ report.actor_kind }} / {{ report.actor }}</dd></div><div><dt>登录方式</dt><dd>{{ report.auth_method }} · {{ report.source_id }} · {{ report.subject }}</dd></div><div><dt>入口与操作</dt><dd>{{ report.surface }} · {{ report.operation }}</dd></div><div><dt>请求</dt><dd>{{ report.method }} {{ report.path }}</dd></div><div><dt>结果</dt><dd>HTTP {{ report.status_code }} · {{ report.duration_ms }} ms · {{ report.error_code||'成功' }}</dd></div><div><dt>目标资源</dt><dd>{{ report.resource_id||'—' }}</dd></div><div><dt>实际账号 / 模式</dt><dd>{{ report.account_username||report.account_id||'—' }} / {{ report.mode||'—' }}</dd></div></dl><h3>请求内容{{ report.request_truncated?'（已截断到 1 KiB）':'' }}</h3><pre>{{ report.request_preview||'无请求体' }}</pre><h3>返回内容{{ report.response_truncated?'（已截断到 1 KiB）':'' }}</h3><pre>{{ report.response_preview||'无返回体' }}</pre><details><summary>完整审计元数据</summary><pre>{{ JSON.stringify(report,null,2) }}</pre></details></template><pre v-else>{{ JSON.stringify(report,null,2) }}</pre></section></div>
  </div>
</template>

<style scoped>
.access-workspace{height:100vh;overflow:auto}
.access-workspace{min-height:100vh;background:#f5f7fa;color:#25344a;font-family:Inter,"PingFang SC",sans-serif;font-size:14px}.access-workspace *{box-sizing:border-box}.access-header{height:66px;display:flex;gap:22px;align-items:center;padding:0 28px;background:white;border-bottom:1px solid #dce3ec}.access-header strong{font-size:17px}.access-header a{color:#3864a4;text-decoration:none}.access-brand{display:flex;align-items:center;gap:10px;font-size:20px;font-weight:700}.access-brand span{display:grid;place-items:center;background:#0875d5;color:white;width:33px;height:33px;border-radius:8px}.access-subtitle{color:#748294;margin-right:auto}.access-workspace button{border:1px solid #ccd6e3;border-radius:6px;background:white;padding:8px 13px;color:#304865;cursor:pointer;font:inherit;display:inline-flex;align-items:center;justify-content:center;gap:8px}.access-workspace button:hover{background:#edf4ff}.access-workspace button:disabled{opacity:.5;cursor:wait}.access-workspace .primary{background:#0875d5;border-color:#0875d5;color:white}.access-workspace input,.access-workspace select,.access-workspace textarea{width:100%;border:1px solid #cbd6e2;border-radius:6px;background:white;padding:9px 10px;font:inherit;color:#263b53;min-width:0}.access-workspace input[type=checkbox]{width:16px;height:16px;accent-color:#0875d5}.access-workspace label{display:flex;flex-direction:column;gap:7px;font-weight:500}.access-workspace small{color:#758295;font-size:12px;font-weight:400;line-height:1.6}.access-workspace p{line-height:1.7;color:#68788e}.access-workspace h1{font-size:25px;margin:0 0 10px}.access-workspace h2{font-size:17px;margin:0 0 14px}.access-workspace h3{font-size:14px;margin:20px 0 8px}.access-workspace pre{background:#f4f7fb;border:1px solid #e1e7f0;border-radius:6px;padding:16px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:560px;overflow:auto;font-size:12px;line-height:1.65}.access-workspace code{background:#edf1f7;padding:2px 5px;border-radius:4px}.access-log