small{display:block;font-family:monospace;margin-top:5px}.access-row-actions{display:flex;flex-wrap:wrap;gap:7px}.access-row-actions button{font-size:12px;padding:6px 10px}.access-badge{display:inline-block;border-radius:12px;padding:4px 9px;white-space:nowrap;font-size:12px}.access-badge.good{background:#e4f4eb;color:#277149}.access-badge.muted{background:#eef1f5;color:#748194}.access-empty{text-align:center;padding:42px!important;color:#8390a3}.access-alert{margin:15px 28px;padding:13px 18px;border-radius:7px;background:#e7f4ed;color:#276044}.access-alert.error{background:#fff0ef;color:#a43e36}.access-secret{background:#fff8e8;border:1px solid #e7c784;border-radius:10px;padding:22px;margin:20px 0}.access-secret input{font-family:monospace;margin-bottom:14px}.access-user-main{max-width:1120px;padding:35px;margin:0 auto}.access-resource-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px;margin:24px 0}.access-resource-cards button{flex-direction:column;align-items:flex-start;padding:20px}.access-resource-cards .selected{border-color:#0875d5;background:#edf5ff}.access-warning{background:#fff4dc;padding:12px;color:#885a16!important}.access-modal-backdrop{position:fixed;inset:0;z-index:1000;background:rgba(20,34,52,.58);display:grid;place-items:center;padding:28px}.access-modal{width:min(1040px,100%);max-height:calc(100vh - 56px);overflow:auto;background:white;border-radius:12px;padding:24px;box-shadow:0 24px 80px rgba(12,28,48,.35)}.access-modal-header{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;position:sticky;top:-24px;background:white;padding:24px 0 12px;z-index:2}.access-modal-header h2{margin:0}.access-modal-header p{margin:5px 0 0}.access-audit-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:#dfe6ef;border:1px solid #dfe6ef;border-radius:8px;overflow:hidden}.access-audit-grid>div{background:#f9fbfd;padding:12px}.access-audit-grid dt{font-size:12px;color:#728198;margin-bottom:5px}.access-audit-grid dd{margin:0;overflow-wrap:anywhere}.access-modal details{margin-top:20px}.access-modal summary{cursor:pointer;color:#3864a4}@media(max-width:850px){.access-header{height:auto;min-height:66px;flex-wrap:wrap;padding:15px;gap:12px}.access-subtitle{display:none}.access-layout{grid-template-columns:170px minmax(0,1fr)}.access-main{padding:18px}.access-fields,.access-audit-grid{grid-template-columns:1fr}.access-filters{grid-template-columns:1fr 1fr}.access-heading{flex-wrap:wrap}}@media(max-width:580px){.access-layout{display:block}.access-layout nav{display:flex;overflow:auto;padding:8px}.access-layout nav button{white-space:nowrap;width:auto}.access-layout nav p{display:none}.access-header strong{display:none}.access-login{margin:35px 15px}.access-main{padding:14px}.access-form,.access-panel{padding:16px}.access-filters{grid-template-columns:1fr}.access-modal-backdrop{padding:8px}.access-modal{padding:16px;max-height:calc(100vh - 16px)}}
</style>
